constexpr uint16_t V3_PROJECTION_MAGIC = 0x4E58; // "XN" on the little-endian wire.
constexpr uint8_t V3_PROJECTION_TRAILER_VERSION = 1;
constexpr uint8_t V3_PROJECTION_TRAILER_OFFSET = 48;

enum V3ProjectionFlag : uint8_t {
  V3ProjectionCapable = 1 << 0,
  V3ProjectionActive = 1 << 1,
};

// This retains the deployed 16-byte marker layout. Fields used by the removed
// fallback negotiation remain zero so older gen1 firmware treats the sender as native.
#pragma pack(push, 1)
struct V3ProjectionTrailer {
  uint16_t magic = V3_PROJECTION_MAGIC;
  uint8_t trailerVersion = V3_PROJECTION_TRAILER_VERSION;
  uint8_t flags = V3ProjectionCapable | V3ProjectionActive;
  DeviceId controlId = 0;
  uint16_t controlSession = 0;
  uint16_t generation = 0;
  uint16_t resumePhrase = 0;
  uint8_t hopCount = 0;
  uint8_t reserved = 0;
  uint16_t crc16 = 0;
};
#pragma pack(pop)

static_assert(sizeof(V3ProjectionTrailer) == 16, "gen0 projection trailer wire size changed");
static_assert(V3_PROJECTION_TRAILER_OFFSET + sizeof(V3ProjectionTrailer) == MESSAGE_DATA_SIZE,
              "gen0 projection trailer must occupy the legacy payload tail");

inline uint16_t v3ProjectionCrc16(const uint8_t* data, uint8_t length) {
  uint16_t crc = 0xFFFF;
  for (uint8_t index = 0; index < length; index++) {
    crc ^= uint16_t(data[index]) << 8;
    for (uint8_t bit = 0; bit < 8; bit++)
      crc = crc & 0x8000 ? uint16_t((crc << 1) ^ 0x1021) : uint16_t(crc << 1);
  }
  return crc;
}

inline void finalizeV3ProjectionTrailer(V3ProjectionTrailer& trailer) {
  trailer.crc16 = 0;
  trailer.crc16 = v3ProjectionCrc16(
      reinterpret_cast<const uint8_t*>(&trailer),
      sizeof(trailer) - sizeof(trailer.crc16)
  );
}

inline bool isValidV3ProjectionTrailer(const V3ProjectionTrailer& trailer) {
  if (trailer.magic != V3_PROJECTION_MAGIC
      || trailer.trailerVersion != V3_PROJECTION_TRAILER_VERSION
      || trailer.reserved != 0
      || !(trailer.flags & V3ProjectionCapable))
    return false;
  return trailer.crc16 == v3ProjectionCrc16(
      reinterpret_cast<const uint8_t*>(&trailer),
      sizeof(trailer) - sizeof(trailer.crc16)
  );
}

inline bool readV3ProjectionTrailer(const NodeMessage& message, V3ProjectionTrailer& trailer) {
  if (message.header.version != TUBES_PROTOCOL_V2)
    return false;
  memcpy(&trailer, message.data + V3_PROJECTION_TRAILER_OFFSET, sizeof(trailer));
  return isValidV3ProjectionTrailer(trailer);
}

inline void writeV3ProjectionTrailer(NodeMessage& message, V3ProjectionTrailer trailer) {
  finalizeV3ProjectionTrailer(trailer);
  memcpy(message.data + V3_PROJECTION_TRAILER_OFFSET, &trailer, sizeof(trailer));
}

